// ---------------------------------------------------------------------------
// The sandbox (mirrors _MemorySandbox: env override pinned to a temp
// .gitcurator; HOME pinned to a home WITHOUT Documents).
// ---------------------------------------------------------------------------

type memSandbox struct {
	t          *testing.T
	globalPath string
	tmp        string
}

func newMemSandbox(t *testing.T) *memSandbox {
	t.Helper()
	tmp := t.TempDir()
	s := &memSandbox{t: t, tmp: tmp, globalPath: filepath.Join(tmp, ".gitcurator")}
	t.Setenv(EnvOverride, s.globalPath)
	home := filepath.Join(tmp, "home")
	if err := os.MkdirAll(home, 0o755); err != nil {
		t.Fatalf("sandbox home: %v", err)
	}
	t.Setenv("HOME", home)
	return s
}

// remember writes a memory file directly (test fixture).
func (s *memSandbox) remember(data string) {
	s.t.Helper()
	if err := os.WriteFile(s.globalPath, []byte(data), 0o644); err != nil {
		s.t.Fatalf("remember: %v", err)
	}
}

// memoryJSON returns the memory file's raw JSON (nil when absent).
func (s *memSandbox) memoryJSON() []byte {
	s.t.Helper()
	raw, err := os.ReadFile(s.globalPath)
	if os.IsNotExist(err) {
		return nil
	}
	if err != nil {
		s.t.Fatalf("read memory: %v", err)
	}
	return raw
}

// treeFromJSON decodes a JSON object into an OrderedMap (UseNumber: the
// memory's numbers keep their literal shapes).
func treeFromJSON(t *testing.T, raw string) *storage.OrderedMap {
	t.Helper()
	om, err := storage.DecodeJSON([]byte(raw))
	if err != nil {
		t.Fatalf("decode %q: %v", raw, err)
	}
	return om
}

