func TestBadEnvParentDoesNotRaise(t *testing.T) {
	s := newMemSandbox(t)
	blocker := filepath.Join(s.tmp, "file-not-dir")
	if err := os.WriteFile(blocker, []byte{}, 0o644); err != nil {
		t.Fatal(err)
	}
	bad := filepath.Join(blocker, "nested", ".gitcurator")
	t.Setenv(EnvOverride, bad)
	if got := GlobalConfigPath(); got != "" {
		t.Fatalf("expected None for uncreatable parent, got %q", got)
	}
}

