func TestVaultKeysHaveTheirOwnFamily(t *testing.T) {
	for _, k := range append(append([]string{}, VaultFlatKeys...), VaultNestedKeys...) {
		if !IsVaultKey(k) {
			t.Errorf("is_vault_key(%q) = false", k)
		}
		if IsCredentialKey(k) {
			t.Errorf("is_credential_key(%q) = true (separate family)", k)
		}
		if !IsRememberedKey(k) {
			t.Errorf("is_remembered_key(%q) = false", k)
		}
	}
	for _, k := range []string{"llm_provider", "dark_mode", "log_level"} {
		if IsVaultKey(k) || IsRememberedKey(k) {
			t.Errorf("%q leaked into the vault/remembered families", k)
		}
	}
}

