func TestFreshVersionRestoresTheCredentialSet(t *testing.T) {
	s := newMemSandbox(t)
	s.remember(`{
          "telegram_api_id": 24611234, "telegram_api_hash": "hash",
          "telegram_phone": "+15550001111", "github_token": "ghp_real",
          "proxy": {"enabled": true, "host": "127.0.0.1", "port": 10808,
                    "type": "socks5", "use_for_web": true},
          "cloudflare_worker_url": "https://bot.example.workers.dev"
        }`)
	fresh := storage.NewOrderedMap()
	fresh.Set("telegram_api_id", 0)
	fresh.Set("telegram_api_hash", "")
	fresh.Set("github_token", "")
	proxy := storage.NewOrderedMap()
	proxy.Set("enabled", false)
	proxy.Set("host", "")
	fresh.Set("proxy", proxy)
	fresh.Set("cloudflare_worker_url", "")
	filled := ApplyGlobalCredentials(fresh, "", true)
	if v, _ := fresh.Get("telegram_api_id"); fmt.Sprint(v) != "24611234" {
		t.Errorf("telegram_api_id = %v", v)
	}
	if v, _ := fresh.Get("github_token"); v != "ghp_real" {
		t.Errorf("github_token = %v", v)
	}
	px, _ := fresh.Get("proxy")
	enabled, _ := px.(*storage.OrderedMap).Get("enabled")
	if enabled != true {
		t.Errorf("proxy.enabled not filled")
	}
	if v, _ := fresh.Get("cloudflare_worker_url"); v != "https://bot.example.workers.dev" {
		t.Errorf("cloudflare_worker_url = %v", v)
	}
	if filled < 6 {
		t.Errorf("filled = %d, want >= 6", filled)
	}
}

