func TestFillNeverMutatesTheSharedExample(t *testing.T) {
	// the order-dependence law: the fresh path copies the example
	// SHALLOWLY, so the fill must never write through the caller's
	// nested dicts.
	s := newMemSandbox(t)
	s.remember(`{"proxy": {"enabled": true}, "github_token": "ghp_real"}`)
	before := storage.PyDumps(constants.ExampleTree())
	fresh := constants.ExampleTree()
	// shallow — the trap: swap in the example's OWN nested proxy object
	proxy, _ := fresh.Get("proxy")
	freshShallow := storage.NewOrderedMap()
	freshShallow.Set("proxy", proxy)
	freshShallow.Set("github_token", "")
	ApplyGlobalCredentials(freshShallow, "", true)
	if got := storage.PyDumps(constants.ExampleTree()); got != before {
		t.Fatal("the shared example was mutated through the fill")
	}
	px, _ := freshShallow.Get("proxy")
	if v, _ := px.(*storage.OrderedMap).Get("enabled"); v != true {
		t.Fatalf("the copy did not fill: enabled = %v", v)
	}
}

