// containsKeyValues checks that every "key": value pair in the compact
// want subset appears in the pretty got dump (the subset is compact JSON;
// the got is the pretty 2-space dump of the whole tree).
func containsKeyValues(got, wantCompact string) bool {
	var want map[string]any
	dec := json.NewDecoder(strings.NewReader(wantCompact))
	dec.UseNumber()
	if err := dec.Decode(&want); err != nil {
		return false
	}
	var gotMap map[string]any
	dec2 := json.NewDecoder(strings.NewReader(got))
	dec2.UseNumber()
	if err := dec2.Decode(&gotMap); err != nil {
		return false
	}
	for k, v := range want {
		if !pyEqualAny(gotMap[k], v) {
			return false
		}
	}
	return true
}

